// The compiled evaluator must behave exactly like the tree-walking one: same worlds, step by step.
import { describe, expect, test } from 'bun:test';
import { readFileSync } from 'node:fs';
import { Parser } from '../src/parser/parser';
import { ASTBuilder } from '../src/ast/astBuilder';
import { validateAST } from '../src/ast/astValidator';
import { buildGame } from '../src/game/builder/builder';
import { createEngine } from '../src/game/game';
import { createEvaluator } from '../src/game/interpreter/interpreter';
import { createCompiledEvaluator } from '../src/game/interpreter/compiler';

function run(file: string, compiled: boolean, setup: [string, number, number][], steps: number) {
  const program = new ASTBuilder().build(new Parser(readFileSync(file, 'utf8')).parse());
  validateAST(program);
  let seed = 7;
  const random = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  const engine = createEngine(buildGame(program), { width: 64, height: 64, random }, compiled ? createCompiledEvaluator() : createEvaluator());
  for (const [type, x, y] of setup) try { engine.place(type, x, y); } catch { /* occupied */ }
  let snap = engine.snapshot();
  for (let i = 0; i < steps; i++) snap = engine.step();
  return JSON.stringify(snap.elements);
}

const block = (type: string, x0: number, y0: number, w: number, h: number) => {
  const out: [string, number, number][] = [];
  for (let x = x0; x < x0 + w; x++) for (let y = y0; y < y0 + h; y++) out.push([type, x, y]);
  return out;
};

describe('compiled evaluator', () => {
  const cases: [string, [string, number, number][]][] = [
    ['examples/falling-sand.sand', block('Sand', 10, 2, 20, 4)],
    ['examples/rain-cloud.sand', block('Cloud', 10, 4, 30, 2)],
    ['examples/fire-and-ice.sand', [...block('Ice', 10, 40, 30, 8), ...block('Fire', 12, 36, 20, 2)]],
    ['examples/sand-and-water.sand', [...block('Water', 5, 40, 40, 6), ...block('Sand', 10, 5, 10, 4)]],
    ['examples/big-sandbox.sand', [...block('Sand', 0, 58, 64, 6), ...block('Water', 0, 50, 64, 5), ['Square', 20, 20], ['Bomb', 40, 30], ...block('Wood', 45, 40, 8, 3), ...block('Fire', 46, 38, 4, 1), ['Thunder', 30, 2]]],
  ];
  for (const [file, setup] of cases) {
    test(`matches the interpreter on ${file}`, () => {
      expect(run(file, true, setup, 40)).toBe(run(file, false, setup, 40));
    });
  }
});
